  overflow: visible;
  min-height: 70vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin-bottom: 4rem;
}

/* Animated Background Orbs */
.usage-hero-bg {
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 0;
}

.usage-hero-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.4;
  animation: float 20s ease-in-out infinite;
}

.usage-hero-orb-1 {
  width: 600px;
  height: 600px;
  background: var(--usage-green);
  top: -200px;
  left: -100px;
  animation-delay: 0s;
}

.usage-hero-orb-2 {
  width: 400px;
  height: 400px;
  background: var(--usage-green-light);
  bottom: -100px;
  right: -50px;
  animation-delay: -7s;
}

.usage-hero-orb-3 {
  width: 300px;
  height: 300px;
  background: var(--usage-green-dark);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  animation-delay: -14s;
}

@keyframes float {
  0%, 100% {
    transform: translate(0, 0) scale(1);
  }
  25% {
    transform: translate(30px, -30px) scale(1.05);
  }
  50% {
    transform: translate(-20px, 20px) scale(0.95);
  }
  75% {
    transform: translate(-30px, -20px) scale(1.02);
  }
}

/* Hero Content */
.usage-hero-content {
  position: relative;
  z-index: 1;
  animation: fadeIn 0.6s ease-out;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4rem;
  max-width: 1100px;
  width: 100%;
}

.usage-hero-text {
  flex: 1;
  text-align: left;
}

.usage-hero-logo-wrapper {
  flex-shrink: 0;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Logo */
.usage-hero-logo {
  width: 280px;
  height: auto;
  filter: drop-shadow(0 4px 20px var(--usage-green-glow));
}

/* Title */
.usage-hero-title {
  font-family: 'VT323', monospace;
  font-size: 5.5rem;
  font-weight: 400;
  margin: 0 0 0.5rem;
  padding: 0.2em 0;
  color: var(--usage-green);
  line-height: 1;
  letter-spacing: 0.02em;
  text-shadow: 0 0 30px var(--usage-green-glow);
}

/* Tagline */
.usage-hero-tagline {
  font-size: 1.5rem;
  color: var(--vp-c-text-2);
  margin: 0 0 1.5rem;
  font-weight: 400;
}

/* Action Buttons */
.usage-hero-actions {
  display: flex;
  gap: 1rem;
  justify-content: flex-start;
  flex-wrap: wrap;
}

.usage-hero-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.2s ease;
}

.usage-hero-btn-primary {
  background: var(--usage-green);
  color: #000;
}

.usage-hero-btn-primary:hover {
  background: var(--usage-green-light);
  transform: scale(1.05);
  box-shadow: 0 4px 20px var(--usage-green-glow);
}

.usage-hero-btn-secondary {
  background: rgba(255, 255, 255, 0.1);
  color: var(--vp-c-text-1);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.usage-hero-btn-secondary:hover {
  background: rgba(255, 255, 255, 0.15);
  transform: scale(1.05);
}

/* Feature Buttons */
.usage-hero-features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
  margin-bottom: 8rem;
  max-width: 480px;
}

.usage-hero-feature {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border-radius: 8px;
  font-size: 0.85rem;
  font-weight: 500;
  text-decoration: none;
  background: rgba(255, 255, 255, 0.05);
  color: var(--vp-c-text-1);
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: all 0.2s ease;
  position: relative;
  cursor: pointer;
}

.usage-hero-feature:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: var(--usage-green);
  transform: translateY(-2px);
  z-index: 10;
}

.usage-hero-feature:hover .usage-hero-feature-tooltip {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.usage-hero-feature-icon {
  font-size: 1rem;
}

.usage-hero-feature-text {
  color: var(--vp-c-text-2);
  white-space: nowrap;
}

.usage-hero-feature:hover .usage-hero-feature-text {
  color: var(--vp-c-text-1);
}

/* Feature Tooltip */
.usage-hero-feature-tooltip {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  background: rgba(30, 30, 30, 0.95);
  border: 1px solid var(--usage-green);
  border-radius: 12px;
  padding: 1rem 1.25rem;
  min-width: 220px;
  max-width: 280px;
  opacity: 0;
  visibility: hidden;
  transition: all 0.2s ease;
  z-index: 100;
  margin-top: 0.75rem;
  text-align: left;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.usage-hero-feature-tooltip::before {
  content: '';
  position: absolute;
  top: -8px;
  left: 50%;
  transform: translateX(-50%);
  border: 8px solid transparent;
  border-bottom-color: var(--usage-green);
  border-top: none;
}

.usage-hero-feature-tooltip strong {
  display: block;
  color: var(--usage-green);
  font-size: 0.9rem;
  margin-bottom: 0.5rem;
}

.usage-hero-feature-tooltip p {
  font-size: 0.85rem;
  color: var(--vp-c-text-2);
  margin: 0;
  line-height: 1.5;
}

/* Responsive */
@media (max-width: 900px) {
  .usage-hero-content {
    flex-direction: column-reverse;
    gap: 2rem;
    text-align: center;
  }

  .usage-hero-text {
    text-align: center;
  }

  .usage-hero-actions {
    justify-content: center;
  }

  .usage-hero-features {
    justify-content: center;
    margin-left: auto;
    margin-right: auto;
  }
}

@media (max-width: 768px) {
  .usage-hero {
    padding: 3rem 1rem 4rem;
    min-height: auto;
  }

  .usage-hero-logo {
    width: 180px;
  }

  .usage-hero-title {
    font-size: 3.5rem;
  }

  .usage-hero-tagline {
    font-size: 1.25rem;
  }

  .usage-hero-features {
    grid-template-columns: repeat(2, 1fr);
    max-width: 320px;
  }
}

