/// Generate a shell completion script for bash, fish, nu, powershell, or zsh
///
/// The script is a shim: on each Tab it hands the words typed so far to `usage complete-word`,
/// so `usage` must be installed wherever the script is. The spec comes from `--file`, or from
/// running `--usage-cmd` at completion time, which keeps a CLI that prints its own spec from
/// ever going stale.
#[derive(Args)]
#[usage(alias = "c", alias_hidden("complete", "completions"), effect = "read")]
pub struct Completion {
    /// The shell to generate the script for
    #[usage(choices("bash", "fish", "nu", "powershell", "zsh"))]
    shell: String,

    /// The name of the CLI being completed, as it is typed at the prompt
    bin: String,

    /// Install the script where this shell looks for it, instead of printing it
    ///
    /// Writes the script file and nothing else: no shell rc file and no PowerShell profile is
    /// edited. Where a shell needs a one-time line of its own — zsh's `fpath+=`, PowerShell's
    /// dot-source — it is printed for you to add.
    #[usage(long, effect = "write")]
    install: bool,

    /// Replace a file at the target path that usage did not write
    #[usage(long, requires = "--install", effect = "write")]
    force: bool,

    /// A usage spec file, or a script with a usage shebang; "-" reads stdin
    #[usage(short, long)]
    file: Option<PathBuf>,

    /// Cache what --usage-cmd prints under this key, so it runs once per key rather than on every Tab; the CLI's version is a good key
    #[usage(long, requires = "--usage-cmd")]
    cache_key: Option<String>,

    /// The `usage` executable the script calls back to, when it is not `usage` on PATH
    #[usage(long, default = "usage", env = "JDX_USAGE_BIN")]
    usage_bin: String,

    /// A command that prints the CLI's spec, run in place of reading --file
    ///
    /// For a CLI that answers with its own spec, such as `mycli __usage_spec__`, so the script
    /// always completes the version that is installed. Required unless --file is given.
    #[usage(long, required_unless = "--file")]
    usage_cmd: Option<String>,
}

impl usage_rs::Run for Completion {
    type Output = usage::miette::Result<()>;

    fn run(self) -> Self::Output {
        // TODO: refactor this
        let spec = match &self.file {
            Some(file) => parse_file_or_stdin(file)?,
            None => Spec::default(),
        };
        let spec = match self.file.is_some() {
            true => Some(spec),
            false => None,
        };
        let opts = CompleteOptions {
            usage_bin: self.usage_bin.clone(),
            shell: self.shell.clone(),
            bin: self.bin.clone(),
            cache_key: self.cache_key.clone(),
            spec,
            usage_cmd: self.usage_cmd.clone(),
            source_file: self.file.as_ref().map(|f| {
                if f.as_os_str() == "-" {
                    "stdin".to_string()
                } else {
                    f.to_string_lossy().to_string()
                }
            }),
        };

        // Trailing newline included: a script is a file, and one without a final newline is a file
        // half the tools that read it complain about.
        let script = format!("{}\n", usage::complete::complete(&opts)?.trim());
        if !self.install {
            // `write_stdout` rather than `println!`, which panics on a broken pipe — and
            // `usage g completion bash mycli | head -1` is an ordinary thing to type.
            return Ok(super::write_stdout(&script)?);
        }
        self.install(&script)
    }
}

impl Completion {
    /// Put the script where this shell looks for it, and say what is left to do.
    ///
    /// The resolver is the one a compiled binary uses to install its own script, so the location is
    /// decided in one place regardless of which side is asking.
    fn install(&self, script: &str) -> usage::miette::Result<()> {
        use usage_rs::install::{self, OnForeign, Wrote};

        let shell = usage_rs::complete::Shell::from_name(&self.shell)
            .ok_or_else(|| usage::miette::miette!("{} has no completion script", self.shell))?;
        // Described from this process rather than reached for inside the resolver, which is what
        // lets a test point the same code path at a directory of its own.
        let env = install::Env::from_process();
        let plan = install::plan(&self.bin, shell, &env).map_err(as_diagnostic)?;

        let done = install::write(
            &plan,
            script,
            if self.force {
                OnForeign::Overwrite
            } else {
                OnForeign::Refuse
            },
        )
        .map_err(as_diagnostic)?;

        // Everything here goes to stderr, and stdout stays empty. A note about a write is not the
        // thing written — the same reason `write_or_stdout` moved its progress line. And after the
        // write rather than before it: a refusal that had already announced an installation would
        // be describing something that did not happen.
        eprintln!("installing to {}", done.plan.path.display());
        if done.wrote == Wrote::Unchanged {
            eprintln!("already up to date");
        }
        if let Some(line) = done.plan.loading.instruction() {
            let file = match &done.plan.loading {
                install::Loading::Manual { file, .. } => file.as_str(),
                _ => "your shell's startup file",
            };
            eprintln!("\nadd this to {file}, once:\n\n{line}\n");
        }
        if let Some(note) = done.plan.note {
            eprintln!("note: {note}");
        }
        Ok(())
    }
}

/// An install failure as something the CLI can print, with the way out where there is one.
///
/// The chain is walked rather than formatted away: `Display` on an install error names the step and
/// the path, and keeps the operating system's own words — "permission denied", "not a directory" —
/// on `source()`. A report built from `Display` alone drops exactly the half a user acts on.
fn as_diagnostic(err: usage_rs::install::Error) -> usage::miette::Report {
    let mut message = err.to_string();
    let mut cause = std::error::Error::source(&err);
    while let Some(next) = cause {
        message.push_str(&format!(": {next}"));
        cause = next.source();
    }
    match &err {
        usage_rs::install::Error::Foreign { .. } => usage::miette::miette!(
            "{message}\n\nPass --force to replace it, or redirect the script yourself."
        ),
        _ => usage::miette::miette!("{message}"),
    }
}
use std::path::PathBuf;

use super::{parse_file_or_stdin, select_view, write_or_stdout};
use usage::docs::markdown::{MarkdownRenderer, MarkdownTemplate};
use usage::error::UsageErr;
use usage_rs::Args;

/// Generate Markdown documentation from a usage spec
///
/// One page by default, or a page per command with --multi. Every part of the output comes
/// from a Tera template that --template can replace.
#[derive(Args)]
#[usage(alias = "md", effect = "read")]
pub struct Markdown {
    /// A usage spec file, or a script with a usage shebang; "-" reads stdin
    #[usage(short, long)]
    file: PathBuf,

    /// Render one spec-declared executable view
    #[usage(long)]
    view: Option<String>,
    // /// Pass a usage spec in an argument instead of a file
    // #[usage(short, long, required_unless = "--file", overrides = "--file")]
    // spec: Option<String>,
    /// Render each subcommand as a separate markdown file
    #[usage(short, long, conflicts = "--out-file")]
    multi: bool,

    /// Escape HTML in markdown
    #[usage(long)]
    html_encode: bool,

    /// Directory for the per-command pages (required with --multi)
    #[usage(
        long,
        value_hint = usage_rs::ValueHint::DirPath,
        requires = "--multi",
        required_if = "--multi",
        effect = "write"
    )]
    out_dir: Option<PathBuf>,

    /// Output file path for single-file markdown generation, or "-" for stdout (default)
    #[usage(
        long,
        value_hint = usage_rs::ValueHint::FilePath,
        effect = "write"
    )]
    out_file: Option<PathBuf>,

    /// Turn four-space indented blocks in help text into markdown code fences
    ///
    /// `--replace-pre-with-code-fences` is the former name and still works. It was always a
    /// misnomer: this has never looked at `<pre>` tags.
    #[usage(
        long = "indented-blocks-to-code-fences",
        alias = "replace-pre-with-code-fences"
    )]
    indented_blocks_to_code_fences: bool,

    /// Prefix for the links between pages, such as /cli/reference
    #[usage(long)]
    url_prefix: Option<String>,

    /// Replace a built-in Tera template, as NAME=PATH; the names are spec, index, command, argument, flag, and config
    #[usage(long)]
    template: Vec<String>,
}

impl usage_rs::Run for Markdown {
    type Output = usage::miette::Result<()>;

    fn run(self) -> Self::Output {
        // The banner belongs to every generated document, so build it in one place rather
        // than once per output path.
        let render = |md: &str| {
            format!(
                "<!-- @generated by usage-cli from usage spec -->\n{}\n",
                md.trim()
            )
        };
        // File-only, deliberately: every path this receives is a join onto `--out-dir`, so a
        // `-` meaning stdout cannot turn up here.
        let write = |path: &PathBuf, md: &str| -> usage::miette::Result<()> {
            eprintln!("writing to {}", path.display());
            super::write_file(path, render(md))?;
            Ok(())
        };
        let spec = select_view(parse_file_or_stdin(&self.file)?, self.view.as_deref())?;
        let mut ctx = MarkdownRenderer::new(spec.clone())
            .with_html_encode(self.html_encode)
            .with_indented_blocks_to_code_fences(self.indented_blocks_to_code_fences);
        for value in &self.template {
            let Some((name, path)) = value.split_once('=') else {
                usage::miette::bail!("invalid template `{value}`; expected NAME=PATH");
            };
            let template = match name {
                "spec" => MarkdownTemplate::Spec,
                "index" => MarkdownTemplate::Index,
                "command" => MarkdownTemplate::Command,
                "argument" => MarkdownTemplate::Argument,
                "flag" => MarkdownTemplate::Flag,
                "config" => MarkdownTemplate::Config,
                _ => usage::miette::bail!(
                    "unknown template `{name}`; expected spec, index, command, argument, flag, or config"
                ),
            };
            let path = PathBuf::from(path);
            let source = std::fs::read_to_string(&path)
                .map_err(|err| UsageErr::FileError(err, path.clone()))?;
            ctx = ctx.with_template(template, source);
        }
        if let Some(url_prefix) = &self.url_prefix {
            ctx = ctx.with_url_prefix(url_prefix);
        }
        if self.multi {
            ctx = ctx.with_multi(true);
            // Before anything is written, so a refusal does not leave a half-built directory.
            //
            // Refused rather than warned about: writing anyway destroys the command's own
            // documentation, and a warning printed into a docs build is a warning nobody reads.
            // No CLI in the fleet has a `configuration` command — they call it `config` — so
            // this asks the one author who ever hits it to pick a name, rather than quietly
            // losing a page for everybody who does not.
            if !ctx.render_config()?.trim().is_empty() {
                if let Some(cmd) = ctx.config_page_collision() {
                    usage::miette::bail!(
                        "the `{cmd}` command's page and the settings page would both be written \
                         to {}; rename the command, or hide it, to generate both",
                        ctx.config_page()
                    );
                }
            }
            let commands = spec.cmd.all_subcommands().into_iter().filter(|c| !c.hide);
            for cmd in commands {
                let md = ctx.render_cmd(cmd)?;
                let dir = cmd
                    .full_cmd
                    .iter()
                    .take(cmd.full_cmd.len() - 1)
                    .map(|c| c.to_string())
                    .collect::<Vec<_>>()
                    .join("/");
                let path = self
                    .out_dir
                    .as_ref()
                    .unwrap()
                    .join(dir)
                    .join(format!("{}.md", cmd.name));
                write(&path, &md)?;
            }
            let md_idx = ctx.render_index()?;
            let path_idx = self.out_dir.as_ref().unwrap().join("index.md");
            write(&path_idx, &md_idx)?;
            // Its own page, and only when there is something to put on it: a CLI with no
            // settings should not gain an empty file in its docs directory.
            let md_config = ctx.render_config()?;
            if !md_config.trim().is_empty() {
                // The same call the index links by, so the two cannot disagree about where the
                // page went.
                let path = self.out_dir.as_ref().unwrap().join(ctx.config_page());
                write(&path, &md_config)?;
            }
        } else {
            let md = ctx.render_spec()?;
            write_or_stdout(self.out_file.as_deref(), &render(&md))?;
        }
        Ok(())
    }
}
# usage-go

> [!CAUTION]
> **usage-go is not ready for any amount of testing.** Unlike the Rust framework
> (`usage-rs`), which is complete enough that `usage-cli` is built with it, usage-go's
> APIs, generated output, and behavior are all still in flux, and parts of what is
> described below only exist in open pull requests. Do not build against it yet.

A CLI framework for Go, built the way [usage-argv](../argv) is built for Rust: the
command line is bound against **static tables** instead of a command tree
assembled at run time.

> **Status: parsing, binding, help, and completions.** `argv` implements the
> [argv grammar](../docs/spec/argv.md) and passes every binding vector in the
> [conformance corpus](../corpus). `usage generate go` emits the tables from a spec,
> along with a typed `Parse` that fills a struct per command. See
> [what is missing](#what-is-missing).

## Why

Every Go CLI framework builds a model of the CLI at run time. cobra constructs a
`cobra.Command` per subcommand, each with its own flag set; urfave/cli assembles the
same shape out of `cli.Command` values; kong walks a struct with reflection. All
three pay for the whole CLI on every invocation, including the two hundred commands
the user did not type.

Measured against a shadow of [mise](https://mise.jdx.dev)'s spec — 211 commands,
711 flags, 128 positionals — parsing `mise use -g node@20`:

|                                 |  one parse | vs usage-go | median |
| ------------------------------- | ---------: | ----------: | -----: |
| **usage-go**, argv → struct     | **5.9 µs** |             | 6.5 µs |
| cobra, build tree + resolve     |     110 µs |        ~18x | 120 µs |
| urfave/cli v3, build tree + run |     200 µs |        ~34x | 220 µs |
| kong, reflect + parse           |     3.0 ms |       ~500x | 3.3 ms |
| usage-go, argv → events         |      73 ns |             |  79 ns |

**In-process parse throughput**: each parser run repeatedly in one process, the
fastest of many short rounds reported. This is the measurement
[`benches/gate/src/bin/time-sweep.rs`](../benches/gate/src/bin/time-sweep.rs) takes
for usage-rs against clap and bpaf, and it is here for the same reason: what a parse
costs is a question about parsing, and a whole Go process is about a millisecond of
runtime startup before `main` — two orders of magnitude larger than the thing being
compared, and varying run to run by more than most of these rows cost. Reproduce with
`mise run perf:go`, which runs
[`benches/go/cmd/sweep`](../benches/go/cmd/sweep/main.go).

The four rows are the same work: from argv to a value the program can use. usage-go's
is `Parse` — bind, apply the post-binding rules, fill the typed structs — because that
is the whole of what the other three do, and comparing our cheapest half against their
whole is how a benchmark flatters its author. The binder alone is the last row, kept out
of the comparison: no other framework here has a stage that answers "which token is
which" and stops.

Each framework's row includes building its model, because that is what it does on every
process start. Hoisting that out would measure a parser against a program that had
already paid for its model, which no CLI gets to do. The collector is switched off
during a round and asked to run between rounds — a process that parses one command line
and gets on with it usually exits before the collector would have run at all, and left
on it lands unevenly enough to move a minimum by 2x.

**All four programs are generated from that one spec**, by `mise run gen-shadow`, and
checked in under [`benches/go`](../benches/go) so a reviewer sees the diff when an
emitter changes. That is what makes this a comparison between parsers rather than
between transcriptions of mise: the hand-written cobra program these replaced was a
third of mise's size, and read as though cobra were three times faster than it is.

What a framework cannot express is printed when its shadow is generated rather than
passed over, since a shadow that quietly dropped half the spec would measure a smaller
CLI. cobra takes every positional as a count rather than as a name, and has no vocabulary
for a short-only flag or a second long form. urfave has no arity check for a single
positional. kong is the one that loses most: 222 flags that a subcommand redeclares
cannot be said at all, because a kong flag reaches every command below the one that
declares it and redeclaring it is a duplicate `kong.New` refuses; and seven commands'
positionals go, because kong cannot mix positionals with subcommands on one node.

### What a whole process costs

The number an adopter feels, and mostly not the parser:

|                                 | instructions | whole process |  binary |
| ------------------------------- | -----------: | ------------: | ------: |
| the Go runtime, parsing nothing |   ~1,010,000 |       1.14 ms |       — |
| **usage-go**, argv → struct     |  **123,293** |   **1.16 ms** | 6.83 MB |
| usage-go, argv → events         |        1,955 |       1.09 ms | 4.80 MB |
| cobra                           |    2,807,995 |       1.62 ms | 3.42 MB |
| urfave/cli v3                   |    5,763,828 |       1.69 ms | 5.48 MB |
| kong                            |   66,688,959 |       5.62 ms | 5.38 MB |

Instruction counts are cachegrind, amortized over 1,000 parses for usage-go and fewer
# Social previews

The docs build generates a 1200×630 PNG per page from its title and usage's
existing logo. The homepage uses a short product description. Images are
rendered locally with resvg and the bundled OFL-licensed Space Grotesk font;
no rendering service or system font is required. Image URLs include a content
hash of the final PNG bytes so title, artwork, font, and renderer changes get a
new URL.

`docs:build` tests text wrapping and PNG rendering, then checks the built HTML
for matching Open Graph/Twitter metadata and the exact image expected from each
page title. Regression tests reject swapped images and empty alt text. Edit
`social-images.mjs` to adjust colors or layout.
Space Grotesk is bundled for deterministic social image generation without
system fonts or network access during the build.

Source: [Google Fonts](https://github.com/google/fonts/tree/main/ofl/spacegrotesk)
