/* Usage Docs Custom Theme — cyberpunk vaporwave */
@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700;900&display=swap');

/* ------------------------------------------------------------------ */
/* Palette                                                             */
/* ------------------------------------------------------------------ */
:root {
  --vw-bg-deep: #0d0221;
  --vw-bg: #120631;
  --vw-bg-raised: #1a0b3d;
  --vw-magenta: #ff2d95;
  --vw-magenta-light: #ff5cab;
  --vw-magenta-glow: rgba(255, 45, 149, 0.4);
  --vw-cyan: #01cdfe;
  --vw-cyan-glow: rgba(1, 205, 254, 0.35);
  --vw-purple: #b967ff;
  --vw-purple-soft: rgba(185, 103, 255, 0.22);
  --vw-mint: #05ffa1;
  --vw-text-bright: #f5f0ff;

  /* VitePress brand + surface overrides (site is force-dark) */
  --vp-c-brand-1: var(--vw-magenta);
  --vp-c-brand-2: var(--vw-magenta-light);
  --vp-c-brand-3: var(--vw-magenta);
  --vp-c-brand-soft: rgba(255, 45, 149, 0.16);
  --vp-c-bg: var(--vw-bg);
  --vp-c-bg-alt: var(--vw-bg-deep);
  --vp-c-bg-elv: var(--vw-bg-raised);
  --vp-c-bg-soft: var(--vw-bg-raised);
  --vp-c-divider: var(--vw-purple-soft);
  --vp-c-gutter: var(--vw-bg-deep);
  --vp-code-block-bg: #150836;
  --vp-c-text-1: var(--vw-text-bright);
  --vp-button-brand-bg: var(--vw-magenta);
  --vp-button-brand-text: #16032e;
  --vp-button-brand-hover-bg: var(--vw-magenta-light);
  --vp-button-brand-hover-text: #16032e;
  --vp-c-tip-1: var(--vw-cyan);
  --vp-c-tip-soft: rgba(1, 205, 254, 0.14);
}

/* ------------------------------------------------------------------ */
/* Chrome: navbar, sidebar, docs                                       */
/* ------------------------------------------------------------------ */
.VPNavBarTitle .title {
  font-family: Orbitron, sans-serif;
  font-weight: 700;
  font-size: 1.05rem;
  letter-spacing: 0.08em;
  color: var(--vw-magenta) !important;
  text-shadow: 0 0 14px var(--vw-magenta-glow);
}

.VPNavBar:not(.home) {
  background: rgba(13, 2, 33, 0.82) !important;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.vp-doc h1 {
  font-family: Orbitron, sans-serif;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.vp-doc a {
  text-decoration-color: var(--vw-purple-soft);
}

.vp-doc div[class*='language-'] {
  border: 1px solid var(--vw-purple-soft);
}

::selection {
  background: var(--vw-magenta);
  color: #16032e;
}

/* ------------------------------------------------------------------ */
/* Hero                                                                */
/* ------------------------------------------------------------------ */
.usage-hero {
  position: relative;
  padding: 4rem 1.5rem 5rem;
  /* clip the glow horizontally without cutting off tile tooltips below */
  overflow-x: clip;
  overflow-y: visible;
  min-height: 72vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: linear-gradient(180deg, var(--vw-bg-deep) 0%, #1c0640 78%, #2a0a4a 100%);
}

/* scanlines */
.usage-hero::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    rgba(255, 255, 255, 0.025) 0px,
    rgba(255, 255, 255, 0.025) 1px,
    transparent 1px,
    transparent 4px
  );
  z-index: 2;
}

/* sun glow behind the illustration */
.usage-hero-glow {
  position: absolute;
  width: 560px;
  height: 560px;
  border-radius: 50%;
  background: radial-gradient(circle, var(--vw-magenta-glow) 0%, rgba(185, 103, 255, 0.18) 45%, transparent 70%);
  filter: blur(40px);
  z-index: 0;
  pointer-events: none;
}

.usage-hero-content {
  position: relative;
  z-index: 3;
  animation: hero-fade-in 0.6s ease-out;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4rem;
  max-width: 1120px;
  width: 100%;
}

.usage-hero-text {
  flex: 1;
  text-align: left;
}

@keyframes hero-fade-in {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Title — Orbitron with chromatic split */
.usage-hero-title {
  font-family: Orbitron, sans-serif;
  font-weight: 900;
  font-size: 4.4rem;
  margin: 0 0 0.75rem;
  color: var(--vw-text-bright);
  line-height: 1.05;
  letter-spacing: 0.04em;
  text-shadow:
    -3px 0 rgba(1, 205, 254, 0.65),
    3px 0 rgba(185, 103, 255, 0.55),
    0 0 28px var(--vw-magenta-glow);
}

.usage-hero-title .accent {
  color: var(--vw-magenta);
}

.usage-hero-tagline {
  font-family: var(--vp-font-family-mono);
  font-size: 1.3rem;
  color: var(--vw-cyan);
  margin: 0 0 2rem;
  text-shadow: 0 0 16px var(--vw-cyan-glow);
}

.usage-hero-tagline .cursor {
  display: inline-block;
  width: 0.6em;
  height: 1.1em;
  margin-left: 0.15em;
  vertical-align: text-bottom;
  background: var(--vw-cyan);
  animation: cursor-blink 1.1s steps(1) infinite;
}

@keyframes cursor-blink {
  50% { opacity: 0; }
}

/* What-is-it description */
.usage-hero-desc {
  font-size: 1.02rem;
  line-height: 1.65;
  color: rgba(245, 240, 255, 0.78);
  max-width: 540px;
  margin: 0 0 2rem;
}

.usage-hero-desc code {
  font-family: var(--vp-font-family-mono);
  font-size: 0.92em;
  color: var(--vw-mint);
  background: rgba(5, 255, 161, 0.08);
  border-radius: 4px;
  padding: 0.1em 0.35em;
}

/* Section labels */
.usage-hero-label {
  font-family: Orbitron, sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--vw-purple);
  margin: 0 0 0.6rem;
}

/* ------------------------------------------------------------------ */
/* Tiles                                                               */
/* ------------------------------------------------------------------ */
.usage-hero-tiles {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-bottom: 1.5rem;
  max-width: 560px;
}

.usage-tile {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.55rem 0.9rem;
  border-radius: 8px;
  font-size: 0.85rem;
  font-weight: 500;
  text-decoration: none;
  color: var(--vw-text-bright);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid var(--vw-purple-soft);
  transition: all 0.2s ease;
  position: relative;
"}

